using UnityEngine;
using System.Collections.Generic;
namespace FalloutPort {
public class PortCombat:MonoBehaviour {
 PortGame game; Material tracerMat,impactMat; readonly Queue<GameObject> marks=new Queue<GameObject>();
 void Awake(){game=GetComponent<PortGame>();tracerMat=Resources.Load<Material>("FalloutFX/Tracer");impactMat=Resources.Load<Material>("FalloutFX/Impact");}
 public void Shot(PortWeaponDefinition definition=null,int pellet=0){var stats=definition?definition.stats:null;bool melee=stats!=null&&stats.reloadType=="melee";float range=stats!=null?(melee?Mathf.Max(1.5f,stats.meleeRange):Mathf.Max(1,stats.range)):90;var camera=game.player.view;Vector3 origin=camera.transform.position;Vector3 direction=camera.transform.forward;if(pellet>0&&stats!=null)direction=(direction+camera.transform.right*Random.Range(-stats.spread,stats.spread)+camera.transform.up*Random.Range(-stats.spread,stats.spread)).normalized;Vector3 end=origin+direction*range;RaycastHit hit;bool struck=Physics.Raycast(origin,direction,out hit,range,~(1<<2),QueryTriggerInteraction.Collide);if(struck)end=hit.point;
  Vector3 muzzle=game.player.weapon.TransformPoint(definition?definition.muzzle:new Vector3(0,.03f,.23f));RaycastHit close;if(Physics.Linecast(origin,muzzle,out close,~(1<<2),QueryTriggerInteraction.Ignore))muzzle=origin+camera.transform.forward*.1f;
  if(Physics.Linecast(muzzle,end,out close,~(1<<2),QueryTriggerInteraction.Ignore)&&(!struck||close.distance<Vector3.Distance(muzzle,end)-.03f)){hit=close;struck=true;end=close.point;}
  if(stats!=null&&(stats.projectile=="missile"||stats.projectile=="mininuke"||stats.projectile=="grenade"||stats.projectile=="mine"||stats.projectile=="plasma")){var projectile=GameObject.CreatePrimitive(PrimitiveType.Sphere);projectile.name=definition.displayName+" projectile";Destroy(projectile.GetComponent<Collider>());projectile.layer=2;projectile.transform.position=muzzle;projectile.transform.localScale=Vector3.one*.08f;projectile.GetComponent<Renderer>().sharedMaterial=tracerMat;var flight=projectile.AddComponent<PortProjectile>();flight.kind=stats.projectile;flight.weaponId=definition.id;flight.velocity=direction*(stats.projectile=="mine"?2:Mathf.Max(10,stats.projectileSpeed));flight.gravity=stats.projectile=="grenade"||stats.projectile=="mininuke"||stats.projectile=="mine";flight.radius=Mathf.Max(.3f,stats.explosionRadius);flight.damage=stats.damage;flight.fuse=flight.gravity?3:6;game.player.Kick();return;}
  if(!melee){var line=new GameObject("Bullet tracer").AddComponent<LineRenderer>();line.sharedMaterial=tracerMat;line.positionCount=2;line.SetPosition(0,muzzle);line.SetPosition(1,end);line.startWidth=stats!=null&&stats.projectile=="flame"?.16f:.012f;line.endWidth=.003f;line.startColor=stats!=null&&stats.damageType=="energy"?new Color(1,.05f,.015f):new Color(1,.76f,.25f);line.endColor=new Color(1,.35f,.08f);line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;Destroy(line.gameObject,melee?.001f:.065f);
  var flash=new GameObject("Muzzle flash").AddComponent<Light>();flash.transform.position=muzzle;flash.color=new Color(1,.68f,.25f);flash.intensity=2;flash.range=2.5f;Destroy(flash.gameObject,.045f);}if(pellet==0)game.player.Kick();
  if(!struck)return;var bug=hit.collider.GetComponentInParent<PortRoach>();var target=hit.collider.GetComponentInParent<PortRangeTarget>();var citizen=hit.collider.GetComponentInParent<PortCitizen>();var worldActor=hit.collider.GetComponentInParent<PortWorldActor>();if(worldActor){worldActor.Hit(stats!=null?stats.damage:20,definition?definition.id:"pistol_10mm",hit.point,direction);PortSurvival.Instance.hitUntil=Time.time+.16f;}else if(bug){bug.Hit(camera.transform.forward,hit.point);PortSurvival.Instance.hitUntil=Time.time+.16f;}else if(target){target.Hit();PortSurvival.Instance.hitUntil=Time.time+.16f;}else if(citizen){citizen.React(camera.transform.position,true);game.notice="Watch your fire! Vault residents are essential to the quest.";}else if(hit.rigidbody&&!hit.rigidbody.isKinematic)hit.rigidbody.AddForceAtPosition(camera.transform.forward*6,hit.point,ForceMode.Impulse);
  Impact(hit,bug!=null);foreach(var resident in FindObjectsByType<PortCitizen>(FindObjectsSortMode.None))if(Vector3.Distance(resident.transform.position,end)<8)resident.React(camera.transform.position,false);
 }
 void Impact(RaycastHit hit,bool organic){if(hit.collider.isTrigger)return;var dot=GameObject.CreatePrimitive(PrimitiveType.Quad);dot.name="Impact mark";Destroy(dot.GetComponent<Collider>());dot.layer=2;dot.transform.position=hit.point+hit.normal*.008f;dot.transform.rotation=Quaternion.LookRotation(-hit.normal);dot.transform.localScale=Vector3.one*(organic?.055f:.075f);dot.GetComponent<Renderer>().sharedMaterial=impactMat;if(hit.rigidbody)dot.transform.SetParent(hit.transform,true);marks.Enqueue(dot);while(marks.Count>48){var old=marks.Dequeue();if(old)Destroy(old);}Destroy(dot,35);}
 void OnDestroy(){foreach(var m in marks)if(m)Destroy(m);}
}
}
